<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,useId} from 'vue'
import {api,APIError,body,type Row} from '../api'
import {randomID} from '../random'
import {confirmAction} from '../confirm'
import {toast} from '../toast'
import SelectField from './SelectField.vue'
import Icon from './Icon.vue'

type Link={label:string;url:string}
type Product=Row&{id:string;version:number;slug:string;name:string;summary:string;markdown:string;icon_media_id:string|null;cover_media_id:string|null;gallery_media_ids:string[];platforms:string[];state:string;published:boolean;featured:boolean;position:number;links:{main:{type:string;url:string};docs_url:string;repositories:Link[]}}
type Upload={id:string;file:File;key:string;target:'icon'|'cover'|'gallery';state:'queued'|'uploading'|'failed';preview:string;error:string;retryable:boolean}
type Attempt={id:string;version:number;key:string;payload:Row;snapshot:string;published:boolean}
type DeleteAttempt={id:string;version:number;key:string;name:string}
const uid=useId(),items=ref<Product[]>([]),loading=ref(true),ready=ref(false),editorReady=ref(false),busy=ref(false),listError=ref(''),error=ref(''),conflict=ref(false),query=ref(''),filter=ref('all'),tab=ref('content'),editorOpen=ref(false)
const formElement=ref<HTMLFormElement>(),nameInput=ref<HTMLInputElement>(),iconInput=ref<HTMLInputElement>(),coverInput=ref<HTMLInputElement>(),galleryInput=ref<HTMLInputElement>()
const blank=():Product=>({id:'',version:0,slug:'',name:'',summary:'',markdown:'',icon_media_id:null,cover_media_id:null,gallery_media_ids:[],platforms:[],state:'development',published:false,featured:false,position:0,links:{main:{type:'web',url:''},docs_url:'',repositories:[]}})
const form=reactive<Product>(blank()),initial=ref(''),uploads=ref<Upload[]>([]),previewURLs=reactive<Record<string,string>>({}),customPlatform=ref(''),uncertain=ref(false),deleteUncertain=ref(false)
const platformOptions=['Web','iOS','Android','macOS','Windows','Linux']
const stateOptions=[{value:'development',label:'开发中'},{value:'available',label:'可用'},{value:'archived',label:'已归档'}]
const linkOptions=[{value:'web',label:'打开网页'},{value:'download',label:'下载'},{value:'store',label:'前往商店'},{value:'other',label:'访问链接'}]
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const fields=(value:Product=form):Row=>({slug:value.slug,name:value.name,summary:value.summary,markdown:value.markdown,icon_media_id:value.icon_media_id||null,cover_media_id:value.cover_media_id||null,gallery_media_ids:[...value.gallery_media_ids],platforms:[...value.platforms],state:value.state,published:value.published,featured:value.featured,position:Number(value.position),links:clone(value.links)})
const snapshot=()=>JSON.stringify(fields()),dirty=computed(()=>snapshot()!==initial.value||uploads.value.length>0||!!customPlatform.value.trim()),uploading=computed(()=>uploads.value.some(u=>u.state==='queued'||u.state==='uploading')),locked=computed(()=>busy.value||uploading.value)
const filtered=computed(()=>[...items.value].sort((a,b)=>a.position-b.position||Number(a.id)-Number(b.id)).filter(p=>(filter.value==='all'||p.published===(filter.value==='published'))&&(!query.value||[p.name,p.summary,p.slug].join(' ').toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))))
const publishedCount=computed(()=>items.value.filter(p=>p.published).length),allPlatforms=computed(()=>[...new Set([...platformOptions,...form.platforms])]),pendingImages=computed(()=>uploads.value.length>0)
let stopped=false,uploadRunning=false,controller:AbortController|undefined,uploadController:AbortController|undefined,pending:Attempt|null=null,pendingDelete:DeleteAttempt|null=null
initial.value=snapshot()
function message(value:unknown){return value instanceof Error?value.message:'操作未完成，请稍后重试。'}
function parse(value:Row,detail=true):Product{
 if(!value||typeof value.id!=='string'||!value.id||!Number.isSafeInteger(value.version)||value.version<1||['slug','name','summary',...(detail?['markdown']:[])].some(k=>typeof value[k]!=='string')||![null,'string'].includes(value.icon_media_id===null?null:typeof value.icon_media_id)||![null,'string'].includes(value.cover_media_id===null?null:typeof value.cover_media_id)||!Array.isArray(value.gallery_media_ids)||value.gallery_media_ids.some((v:unknown)=>typeof v!=='string')||!Array.isArray(value.platforms)||value.platforms.some((v:unknown)=>typeof v!=='string')||!stateOptions.some(s=>s.value===value.state)||typeof value.published!=='boolean'||typeof value.featured!=='boolean'||!Number.isInteger(value.position)||!value.links||!linkOptions.some(s=>s.value===value.links.main?.type)||typeof value.links.main?.url!=='string'||typeof value.links.docs_url!=='string'||!Array.isArray(value.links.repositories)||value.links.repositories.some((v:Row)=>typeof v.label!=='string'||typeof v.url!=='string'))throw new Error('产品数据未完整载入，当前输入已保留。请重试读取。')
 return {...clone(value),markdown:detail?value.markdown:''} as Product
}
function parseList(data:Row){if(!Array.isArray(data.items))throw new Error('产品列表未完整载入，请重试。');return data.items.map((value:Row)=>parse(value,false))}
function clearUploads(){uploads.value.forEach(u=>{if(u.preview)URL.revokeObjectURL(u.preview)});uploads.value=[]}
function rememberImages(value:Product){if(value.icon_media_id&&value.icon_url)previewURLs[value.icon_media_id]=value.icon_url;if(value.cover_media_id&&value.cover_url)previewURLs[value.cover_media_id]=value.cover_url;for(const image of value.gallery||[])if(image.media_id&&image.url)previewURLs[image.media_id]=image.url}
function fill(value?:Product){clearUploads();Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,value?clone(value):blank());if(value)rememberImages(value);initial.value=snapshot();conflict.value=false;error.value='';pending=null;uncertain.value=false;pendingDelete=null;deleteUncertain.value=false;customPlatform.value=''}
function mediaURL(id:string|null){return id?(previewURLs[id]||'/media/'+id):''}
function iconURL(value:Product){return value.icon_media_id?mediaURL(value.icon_media_id):value.icon_url||''}
function stateLabel(value:string){return stateOptions.find(v=>v.value===value)?.label||value}
function validURL(value:string){if(!value.trim())return true;if(value.startsWith('/')&&!value.startsWith('//'))return !/[\s\\]/.test(value);try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password}catch{return false}}
function problem(){if(!form.name.trim())return '请填写产品名称。';if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(form.slug)||form.slug.length>96)return '产品地址只能包含小写字母、数字和单个连字符，最多96个字符。';if(!Number.isInteger(Number(form.position))||form.position<0||form.position>1000000)return '排序须为0至1000000之间的整数。';if(!validURL(form.links.main.url)||!validURL(form.links.docs_url))return '请检查产品链接，使用站内路径或完整的 HTTP / HTTPS 地址。';if(form.links.repositories.some(link=>!link.label.trim()||!link.url.trim()||!/^https?:\/\//i.test(link.url)||!validURL(link.url)))return '请为每个相关项目填写名称与完整地址。';if(pendingImages.value)return '请先重试或移除未完成的图片上传，再保存产品。';return ''}
async function load(refresh=false){if(locked.value)return;busy.value=true;loading.value=true;listError.value='';controller?.abort();controller=new AbortController();try{const result=parseList(await api('/admin/products',{signal:controller.signal}));if(stopped)return;items.value=result;result.forEach(rememberImages);ready.value=true;if(!editorReady.value){const first=result[0];fill(first?parse(await api('/admin/products/'+first.id)):undefined);editorReady.value=true}if(refresh)toast.success('产品列表已刷新，当前输入已保留。')}catch(e){if(!stopped&&(e as Error).name!=='AbortError')listError.value=message(e)}finally{if(!stopped){loading.value=false;busy.value=false}}}
async function edit(value?:Product){if(locked.value||!ready.value)return;if(deleteUncertain.value){toast.warning('请先重试确认删除结果，再切换产品。');return;}if((dirty.value||uncertain.value)&&!await confirmAction('切换正在编辑的产品？',uncertain.value?'有一次保存尚未确认。切换前建议重试确认保存；继续切换会保留服务器已收到的内容。':'当前未保存的产品修改将放弃。','切换产品'))return;busy.value=true;try{const detail=value?parse(await api('/admin/products/'+value.id)):undefined;if(stopped)return;fill(detail);editorReady.value=true;tab.value='content';editorOpen.value=true;busy.value=false;await nextTick();nameInput.value?.focus({preventScroll:true});formElement.value?.scrollIntoView({block:'start',behavior:'instant'})}catch(e){toast.error(message(e))}finally{busy.value=false}}

async function back(){if(locked.value)return;if(deleteUncertain.value){toast.warning('请先重试确认删除结果，再返回产品列表。');return;}if((dirty.value||uncertain.value)&&!await confirmAction('返回产品列表？','当前输入保留在编辑区，重新打开产品前会提示确认。','返回列表'))return;editorOpen.value=false;await nextTick();document.getElementById(uid+'-new')?.focus()}
async function save(published?:boolean){
 if(locked.value||conflict.value||!editorReady.value||deleteUncertain.value)return
 if(uncertain.value&&published!==undefined)return
 if(!pending){const desired=published??form.published;const issue=problem();if(issue){error.value=issue;return}if(form.published&&!desired&&!await confirmAction('撤回「'+form.name+'」？','产品将从公开页面移除，内容仍保留在后台。','撤回产品'))return;const payload={...fields(),published:desired};pending={id:form.id,version:form.version,key:randomID(),payload,snapshot:snapshot(),published:desired}}
 const attempt=pending;busy.value=true;error.value=''
 try{const result=parse(await api(attempt.id?'/admin/products/'+attempt.id:'/admin/products',{method:attempt.id?'PUT':'POST',...(attempt.id?{version:attempt.version}:{}),key:attempt.key,body:body(attempt.payload)}));if(stopped)return;const local=fields(),preserve=snapshot()!==attempt.snapshot;const at=items.value.findIndex(p=>p.id===result.id);if(at<0)items.value.push(result);else items.value[at]=result;fill(result);if(preserve){Object.assign(form,local,{id:result.id,version:result.version,slug:result.slug,published:result.published});toast.warning('上次保存已确认，当前新修改仍未保存。')}else toast.success(attempt.published?'产品已保存并公开。':'产品已保存，仅后台可见。')}
 catch(e){if(stopped)return;if(e instanceof APIError&&form.id&&(e.code==='VERSION_CONFLICT'||e.status===412)){pending=null;uncertain.value=false;conflict.value=true;error.value='产品已在其他位置更新，当前输入已保留。可以载入最新版本，或另存为新产品。'}else if(e instanceof APIError&&e.status>=400&&e.status<500&&![408,429].includes(e.status)){pending=null;uncertain.value=false;error.value=e.code==='CONFLICT'&&!form.id?'这个产品地址已被使用。请修改产品地址后重新保存，当前内容已保留。':message(e)}else{uncertain.value=true;error.value='暂未确认保存结果。当前输入已保留，请重试确认保存。';toast.error(message(e))}}
 finally{if(!stopped)busy.value=false}
}
async function latest(){if(locked.value||!form.id)return;if(dirty.value&&!await confirmAction('载入服务器最新产品？','当前未保存输入将由最新版本替换。','载入最新'))return;busy.value=true;error.value='';try{const result=parse(await api('/admin/products/'+form.id));if(stopped)return;const at=items.value.findIndex(p=>p.id===result.id);if(at>=0)items.value[at]=result;fill(result);toast.success('已载入最新产品。')}catch(e){error.value=message(e);conflict.value=true}finally{busy.value=false}}
function saveAsNew(){if(locked.value)return;form.id='';form.version=0;form.slug=Array.from(form.slug).slice(0,86).join('')+'-copy';form.published=false;pending=null;uncertain.value=false;conflict.value=false;error.value='';toast.info('内容已保留。请确认新地址后保存为新产品。')}
async function remove(){
 if(locked.value||!form.id||uncertain.value)return
 if(!pendingDelete){if(!await confirmAction('删除「'+form.name+'」？','产品和公开详情页将移除，删除后无法恢复。上传的媒体文件会保留。','删除产品'))return;pendingDelete={id:form.id,version:form.version,key:randomID(),name:form.name}}
 const attempt=pendingDelete;busy.value=true;error.value=''
 try{await api('/admin/products/'+attempt.id,{method:'DELETE',version:attempt.version,key:attempt.key});if(stopped)return;items.value=items.value.filter(p=>p.id!==attempt.id);fill();editorReady.value=true;editorOpen.value=false;toast.success('产品已删除。')}
 catch(e){if(stopped)return;if(e instanceof APIError&&e.status>=400&&e.status<500&&![408,429].includes(e.status)){pendingDelete=null;deleteUncertain.value=false;if(e.code==='VERSION_CONFLICT'||e.status===412){conflict.value=true;error.value='产品已在其他位置更新，删除未执行。请载入最新版本后重试。'}else error.value=message(e)}else{deleteUncertain.value=true;error.value='暂未确认「'+attempt.name+'」的删除结果。请重试确认删除；确认前保留当前输入。';toast.error(message(e))}}
 finally{if(!stopped)busy.value=false}
}

function slugFromName(){if(form.id||form.slug)return;const value=form.name.toLocaleLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,96);if(value)form.slug=value}
function addPlatform(){const value=customPlatform.value.trim();if(!value)return;if(Array.from(value).length>40||form.platforms.length>=12){error.value='平台名称最多40个字符，最多添加12个平台。';return}if(!form.platforms.some(p=>p.toLocaleLowerCase()===value.toLocaleLowerCase()))form.platforms.push(value);customPlatform.value=''}
function pickImages(event:Event,target:Upload['target']){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(locked.value)return;const count=target==='gallery'?12-form.gallery_media_ids.length-uploads.value.filter(u=>u.target==='gallery').length:1;if(files.length>count)toast.warning(target==='gallery'?'截图最多12张，已保留可添加的图片。':'每次选择一张图片。');for(const file of files.slice(0,count)){const issue=!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)?'请选择 JPEG、PNG、WebP 或 GIF 图片。':file.size>10485760?'图片超过10 MiB，请压缩后重新选择。':!file.size?'图片文件为空，请重新选择。':'';uploads.value.push({id:randomID(),file,key:randomID(),target,state:issue?'failed':'queued',preview:issue?'':URL.createObjectURL(file),error:issue,retryable:!issue})}void processUploads()}
async function processUploads(){if(uploadRunning||stopped)return;uploadRunning=true;try{while(!stopped){const upload=uploads.value.find(u=>u.state==='queued');if(!upload)break;upload.state='uploading';upload.error='';uploadController=new AbortController();try{const data=new FormData();data.append('file',upload.file,upload.file.name);const result=await api('/media',{method:'POST',body:data,key:upload.key,signal:uploadController.signal});if(stopped)return;if(result.state!=='ready'||typeof result.media_id!=='string'||!result.media_id)throw new Error('服务器尚未确认图片可用，请重试。');previewURLs[result.media_id]=result.private_preview_url||'/media/'+result.media_id;if(upload.target==='icon')form.icon_media_id=result.media_id;else if(upload.target==='cover')form.cover_media_id=result.media_id;else if(!form.gallery_media_ids.includes(result.media_id))form.gallery_media_ids.push(result.media_id);discardUpload(upload);toast.success('图片已上传，保存产品后生效。')}catch(e){if(!stopped){upload.state='failed';upload.error=message(e);toast.error(upload.error)}}finally{uploadController=undefined}}}finally{uploadRunning=false}}
function discardUpload(upload:Upload){if(upload.preview)URL.revokeObjectURL(upload.preview);uploads.value=uploads.value.filter(u=>u.id!==upload.id)}
function retryUpload(upload:Upload){if(locked.value||!upload.retryable)return;upload.state='queued';void processUploads()}
async function moveScreenshot(index:number,step:number){if(locked.value)return;const to=index+step;if(to<0||to>=form.gallery_media_ids.length)return;const [id]=form.gallery_media_ids.splice(index,1);form.gallery_media_ids.splice(to,0,id);await nextTick();document.getElementById(uid+'-screenshot-'+id)?.focus()}
function tabKey(event:KeyboardEvent){const buttons=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]'));let to=buttons.indexOf(event.target as HTMLButtonElement);if(event.key==='ArrowRight')to=(to+1)%buttons.length;else if(event.key==='ArrowLeft')to=(to+buttons.length-1)%buttons.length;else if(event.key==='Home')to=0;else if(event.key==='End')to=buttons.length-1;else return;event.preventDefault();buttons[to].click();buttons[to].focus()}
function beforeLeave(event:BeforeUnloadEvent){if(dirty.value||uncertain.value||deleteUncertain.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeLeave)})
onBeforeUnmount(()=>{stopped=true;controller?.abort();uploadController?.abort();clearUploads();window.removeEventListener('beforeunload',beforeLeave)})
</script>

<template>
 <section class="product-manager" :class="{'editor-open':editorOpen}">
  <div v-if="listError" class="notice error" role="alert">{{listError}} <button :disabled="locked||loading" @click="load(ready)">重试读取列表</button></div>
  <p v-if="loading" class="muted" role="status">正在读取产品…</p>
  <div class="product-manager-workspace">
   <section class="product-library" aria-label="已保存的产品">
    <div class="product-library-heading"><span v-if="ready">{{items.length}} 个产品 · {{publishedCount}} 个公开</span><span v-else>产品列表</span><button :id="uid+'-new'" class="primary" :disabled="locked||!ready||deleteUncertain" @click="edit()">添加产品</button></div>
    <div class="product-library-filters"><label class="sr-only" :for="uid+'-search'">搜索产品</label><input :id="uid+'-search'" v-model="query" type="search" placeholder="搜索产品" :disabled="!ready"><SelectField v-model="filter" label="公开状态" :disabled="!ready" :options="[{value:'all',label:'全部产品'},{value:'published',label:'已公开'},{value:'draft',label:'仅后台'}]"/></div>
    <button v-for="product in filtered" :key="product.id" type="button" class="product-library-row" :class="{'is-selected':form.id===product.id}" :disabled="locked||deleteUncertain" :aria-pressed="form.id===product.id" @click="edit(product)"><span class="product-manager-icon" aria-hidden="true"><img v-if="iconURL(product)" :src="iconURL(product)" width="44" height="44" alt=""><span v-else>{{Array.from(product.name)[0]}}</span></span><span class="product-library-copy"><strong>{{product.name}}</strong><small>{{product.published?'已公开':'仅后台'}} · {{stateLabel(product.state)}}</small></span><Icon name="arrow" :size="16"/></button>
    <div v-if="ready&&!filtered.length" class="product-library-empty"><h2>{{items.length?'没有匹配的产品':'还没有产品'}}</h2><p>{{items.length?'试试其他名称或公开状态。':'添加真实的产品介绍、界面与访问入口。'}}</p><button v-if="items.length" type="button" class="quiet" @click="query='';filter='all'">清除筛选</button></div>
    <a v-if="ready" class="product-library-public text-link" href="/products" target="_blank" rel="noopener">查看产品页<Icon name="arrow" :size="16"/></a>
   </section>
   <form ref="formElement" class="product-composer" aria-label="产品编辑" novalidate @submit.prevent="save()">
    <div class="product-composer-heading"><button type="button" class="quiet product-editor-back" :disabled="locked||deleteUncertain" @click="back"><Icon name="arrow" :size="16"/>产品列表</button><div><h2>{{form.id?'编辑产品':'添加产品'}}</h2><span v-if="dirty" role="status">有未保存的修改</span></div><a v-if="form.id&&form.published" class="button quiet" :href="'/products/'+form.slug" target="_blank" rel="noopener">公开详情<Icon name="arrow" :size="16"/></a></div>
    <div v-if="error" class="notice error product-editor-error" role="alert">{{error}}<div v-if="conflict" class="actions"><button type="button" :disabled="locked" @click="latest">载入最新版本</button><button type="button" :disabled="locked" @click="saveAsNew">另存为新产品</button></div><button v-else-if="deleteUncertain" type="button" :disabled="locked" @click="remove">重试确认删除</button><button v-else-if="uncertain" type="button" :disabled="locked" @click="save()">重试确认保存</button></div>
    <div class="settings-tabs product-editor-tabs" role="tablist" aria-label="产品编辑分区" @keydown="tabKey"><button v-for="section in [{id:'content',label:'介绍'},{id:'images',label:'图片'},{id:'links',label:'链接'}]" :id="uid+'-tab-'+section.id" :key="section.id" type="button" role="tab" :tabindex="tab===section.id?0:-1" :aria-selected="tab===section.id" :aria-controls="uid+'-panel-'+section.id" @click="tab=section.id">{{section.label}}</button></div>
    <fieldset :disabled="locked||!editorReady||deleteUncertain">
     <div :id="uid+'-panel-content'" v-show="tab==='content'" class="product-editor-fields" role="tabpanel" :aria-labelledby="uid+'-tab-content'">
      <div class="product-editor-pair"><label :for="uid+'-name'">产品名称<input :id="uid+'-name'" ref="nameInput" v-model="form.name" required maxlength="100" @blur="slugFromName"></label><label :for="uid+'-slug'">产品地址<input :id="uid+'-slug'" v-model="form.slug" :disabled="locked||!!form.id||!editorReady" required maxlength="96" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="my-product" spellcheck="false" autocomplete="off"><small>{{form.id?'创建后的地址保持不变，名称可随时修改。':'小写字母、数字与连字符，创建后保持不变。'}}</small></label></div>
      <label :for="uid+'-summary'">简短介绍<textarea :id="uid+'-summary'" v-model="form.summary" maxlength="600" rows="3" placeholder="介绍这个产品能做什么"></textarea></label>
      <label :for="uid+'-markdown'">详细介绍<textarea :id="uid+'-markdown'" v-model="form.markdown" rows="12" class="product-markdown" placeholder="使用 Markdown 记录功能、用法与产品进展"></textarea><small>公开详情页使用站内 Markdown 渲染。</small></label>
      <div class="product-editor-pair"><SelectField v-model="form.state" label="产品状态" :disabled="locked||!editorReady" :options="stateOptions"/><label :for="uid+'-position'">排序<input :id="uid+'-position'" v-model.number="form.position" type="number" min="0" max="1000000" step="1" required><small>数字较小的在前。</small></label></div>
